#!/usr/bin/env python3
# BlueFish Patrimoine : fiche publique, Laurent Le Grin et logo officiel
import base64, hashlib, json, zlib
from pathlib import Path
PATCHES = json.loads(zlib.decompress(base64.b64decode('')))
ready = []
for patch in PATCHES:
    path = Path(patch['path'])
    old = path.read_bytes() if path.exists() else None
    digest = hashlib.sha256(old).hexdigest() if old is not None else None
    if digest == patch['new']:
        continue
    if digest != patch['old']:
        raise SystemExit('Refus : fichier modifie depuis la preparation : ' + str(path))
    new = old or b''
    for start, end, replacement in reversed(patch['changes']):
        new = new[:start] + base64.b64decode(replacement) + new[end:]
    assert hashlib.sha256(new).hexdigest() == patch['new'], str(path)
    ready.append((path,new))
for path,new in ready:
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_bytes(new)
print(len(ready),'fichiers mis a jour.')
